-- Array element assignment in PL/pgSQL and UPDATE, including record fields.
CREATE TYPE ca AS (a int[], b text);
CREATE FUNCTION fa() RETURNS ca LANGUAGE plpgsql AS $$ DECLARE r ca; BEGIN r.a := '{1,2}'; r.a[1] := 9; r.a[3] := 7; RETURN r; END $$;
SELECT fa();
CREATE TABLE ta (k int, a int[]);
CREATE FUNCTION fb() RETURNS int[] LANGUAGE plpgsql AS $$ DECLARE r ta; BEGIN r.a[2] := 5; RETURN r.a; END $$;
SELECT fb();
CREATE FUNCTION fc() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r record; BEGIN r := row(1, '{1}'::int[]); r.f2[1] := 3; RETURN r::text; END $$;
SELECT fc();
CREATE FUNCTION fe() RETURNS ca LANGUAGE plpgsql AS $$ DECLARE r ca; BEGIN r.b[1] := 'x'; RETURN r; END $$;
SELECT fe();
CREATE FUNCTION ff() RETURNS int[] LANGUAGE plpgsql AS $$ DECLARE x int[] := '{1,2}'; BEGIN x[1] := 9; x[4] := 3; x[-1] := 0; RETURN x; END $$;
SELECT ff();
CREATE FUNCTION fg() RETURNS int[] LANGUAGE plpgsql AS $$ DECLARE x int[] := '{{1,2},{3,4}}'; BEGIN x[2][1] := 8; RETURN x; END $$;
SELECT fg();
CREATE FUNCTION fh() RETURNS int[] LANGUAGE plpgsql AS $$ DECLARE x int[] := '{{1,2},{3,4}}'; BEGIN x[3][1] := 8; RETURN x; END $$;
SELECT fh();
CREATE FUNCTION fi() RETURNS int[] LANGUAGE plpgsql AS $$ DECLARE x int[] := '{{1,2},{3,4}}'; BEGIN x[1] := 8; RETURN x; END $$;
SELECT fi();
CREATE FUNCTION fj() RETURNS text[] LANGUAGE plpgsql AS $$ DECLARE x text[]; BEGIN x[2][3] := 'a'; RETURN x; END $$;
SELECT fj(), array_dims(fj());
CREATE FUNCTION fk() RETURNS int[] LANGUAGE plpgsql AS $$ DECLARE x int[] := '{1}'; i int; BEGIN x[i] := 1; RETURN x; END $$;
SELECT fk();
CREATE FUNCTION fl() RETURNS numeric[] LANGUAGE plpgsql AS $$ DECLARE x numeric[] := '{1}'; BEGIN x[2] := 5; x[3] := 2.5; RETURN x; END $$;
SELECT fl();
CREATE TABLE tu (k int, a int[]);
INSERT INTO tu VALUES (1, '{1,2}'), (2, NULL);
UPDATE tu SET a[2] = 7;
UPDATE tu SET a[5] = 1 WHERE k = 1;
SELECT * FROM tu ORDER BY k;
DROP TABLE ta, tu;
DROP FUNCTION fa(), fb(), fc(), fe(), ff(), fg(), fh(), fi(), fj(), fk(), fl();
DROP TYPE ca;
